contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _am) public payable {
        // make sure the only user (this contract) has a positive balance
        c.Deposit{value: 1 ether}();
        uint balBefore = c.balances(address(this));
        uint sumBefore = balBefore + c.balances(address(0xdeadbeef));
        uint cBalBefore = address(c).balance;

        // deciding call: cash out _am, capture revert status
        (bool ok, ) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", _am));
        uint balAfter = c.balances(address(this));
        uint sumAfter = balAfter + c.balances(address(0xdeadbeef));

        assert(
            (ok && balAfter == balBefore - _am && sumAfter == sumBefore) ||
            (!ok && balAfter == balBefore && sumAfter == sumBefore)
        );
    }

    receive() external payable {}
}

