contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount);

        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));
        uint cBefore = address(c).balance;
        uint selfBefore = address(this).balance;

        bool reverted;
        if (cashOutAmount <= balBefore) {
            try c.CashOut(cashOutAmount) { reverted = false; } catch { reverted = true; }
        } else {
            try c.CashOut(cashOutAmount) { reverted = false; } catch { reverted = true; }
        }

        uint balAfter = c.balances(address(this));
        uint cAfter = address(c).balance;
        uint selfAfter = address(this).balance;

        if (!reverted) {
            assert(balBefore - balAfter == cashOutAmount);
            assert(selfAfter == selfBefore + cashOutAmount);
        } else {
            assert(balAfter == balBefore);
            assert(cAfter == cBefore);
        }
    }

    receive() external payable {}
}

